DECLARE
  paquete jsonb := $polo${"ley":{"id":"1f700fdd-9eca-53fe-8188-45988d86394d","siglas":"PODECOBI-TOPOLOBAMPO-M1","titulo":"ACUERDO por el que se modifica el diverso por el que se emite la Declaratoria del Polo de Desarrollo Económico para el Bienestar Topolobampo, Sinaloa, publicado el 20 de marzo de 2026.","tipo":"acuerdo","fecha_publicacion":"2026-04-29","url_original":"https://sidof.segob.gob.mx/notas/docFuente/5786253","temas_clave":["PODECOBI","Declaratoria","Topolobampo","Sinaloa","Acuerdo modificatorio"]},"articulos":[{"id":"ca5a427c-f4b5-5e9e-b2a1-e16366f91fa0","ley_id":"1f700fdd-9eca-53fe-8188-45988d86394d","orden":1,"identificador":"Preámbulo y considerandos","contenido":"<p>ACUERDO por el que se modifica el diverso por el que se emite la Declaratoria del Polo de Desarrollo Económico para el Bienestar Topolobampo, Sinaloa, publicado el 20 de marzo de 2026.</p>\n<p>Al margen un sello con el Escudo Nacional, que dice: Estados Unidos Mexicanos.- Secretaría de Economía.</p>\n<p>MARCELO LUIS EBRARD CASAUBON, Secretario de Economía, con fundamento en los artículos 34 de la Ley Orgánica de la Administración Pública Federal; segundo párrafo, Décimo, tercer párrafo del Decreto por el que se otorgan estímulos fiscales en los Polos de Desarrollo Económico para el Bienestar; 5, fracciones XVII y XXIV, del Reglamento Interior de la Secretaría de Economía, y los lineamientos 2, fracción XIV, 4, fracción II, 8, segundo párrafo del Acuerdo por el que se emiten los Lineamientos para los Polos de Desarrollo Económico para el Bienestar, y</p>\n<p>CONSIDERANDO</p>\n<p>Que de conformidad con lo dispuesto en los artículos 25 y 26, apartado A de la Constitución Política de los Estados Unidos Mexicanos, corresponde al Estado la rectoría del desarrollo nacional mediante la competitividad, el fomento del crecimiento económico, el empleo, así como una justa distribución del ingreso y la riqueza, para garantizar que ésta sea integral y sustentable y que permita el pleno ejercicio de la libertad y la dignidad de los individuos, grupos y clases sociales. Al desarrollo económico nacional concurrirán, con responsabilidad social, el sector público, el sector social y el sector privado, sin menoscabo de otras formas de actividad económica que contribuyan al desarrollo de la Nación;</p>\n<p>Que el Plan Nacional de Desarrollo 2025-2030, publicado en el Diario Oficial de la Federación (DOF) el 15 de abril de 2025, considera al &quot;Plan México&quot; como una herramienta de largo plazo que sustenta una estrategia de industrialización en el país incrementando la participación de las empresas mexicanas en la cadena de proveeduría de las exportaciones y en la generación de productos para consumo nacional; permitiendo a las empresas nacionales, desde micro, pequeñas y medianas hasta grandes corporaciones, tener un papel más activo en la manufactura de bienes intermedios, insumos y componentes esenciales;</p>\n<p>Que en ese sentido, el &quot;Plan México&quot;, presentado por la Presidenta de los Estados Unidos Mexicanos el 13 de enero de 2025, es una estrategia de desarrollo nacional que busca fortalecer el mercado interno y los mercados regionales para posicionar a México en las diez principales economías del mundo y reducir la pobreza y la desigualdad. Esta estrategia también busca promover el desarrollo económico sostenible y equitativo en todo el país; generar empleos dignos y bien remunerados; fortalecer el progreso científico, tecnológico y la innovación; ampliar el acceso a la educación media superior y superior y su vínculo con el Plan Nacional de Desarrollo, a fin de alcanzar el bienestar de las mexicanas y los mexicanos;</p>\n<p>Que en la estrategia prevista en el numeral 7 de las Estrategias del Plan México, previstas en el Plan Nacional de Desarrollo 2025-2030, se establece el &quot;Promover los polos de desarrollo y de bienestar a partir de vocaciones regionales&quot;;</p>\n<p>Que con fecha 20 de marzo de 2026, se publicó en el DOF el Acuerdo por el que se emite la Declaratoria del Polo de Desarrollo Económico para el Bienestar Topolobampo, Sinaloa, y</p>\n<p>Que en consecuencia, resulta necesario modificar el Acuerdo antes señalado, en virtud de que se requiere precisar las coordenadas de los polígonos dentro de los cuales se instaurará el Polo de Desarrollo Económico para el Bienestar Topolobampo, Sinaloa, por lo que se ha tenido a bien emitir el siguiente</p>\n<p>ACUERDO POR EL QUE SE MODIFICA EL DIVERSO POR EL QUE SE EMITE LA DECLARATORIA DEL POLO DE DESARROLLO ECONÓMICO PARA EL BIENESTAR TOPOLOBAMPO, SINALOA, PUBLICADO EN EL DIARIO OFICIAL DE LA FEDERACIÓN EL 20 DE MARZO DE 2026</p>","tipo_articulo":"preambulo","titulo_nombre":"Topolobampo","capitulo_nombre":"Acuerdo modificatorio","seccion_nombre":null},{"id":"bb91f012-7b25-54b8-befc-ac4287700998","ley_id":"1f700fdd-9eca-53fe-8188-45988d86394d","orden":2,"identificador":"Artículo único","contenido":"<p>Artículo Único. - Se reforma el ARTÍCULO TERCERO, fracción I, del Acuerdo por el que se emite la Declaratoria del Polo de Desarrollo Económico para el Bienestar Topolobampo, Sinaloa, publicado en el Diario Oficial de la Federación el 20 de marzo de 2026, para quedar como sigue:</p>\n<p>&quot;ARTÍCULO TERCERO. ...</p>\n<p>I. Criterio de Macro Localización</p>\n<table><thead><tr><th colspan=\"4\">CUADRO DE CONSTRUCCIÓN DEL POLIGONO 1</th></tr><tr><th colspan=\"2\">LADO</th><th colspan=\"2\">COORDENADAS UTM 12 N</th></tr><tr><th>Estación</th><th>Punto visado</th><th>COORDENADA EN X</th><th>COORDENADA EN Y</th></tr></thead><tbody><tr><td>6a</td><td>7</td><td>695236.0540</td><td>2838142.9480</td></tr><tr><td>7</td><td>8</td><td>695197.0170</td><td>2837974.8830</td></tr><tr><td>8</td><td>9</td><td>695176.6610</td><td>2837888.9480</td></tr><tr><td>9</td><td>10</td><td>695155.5030</td><td>2837799.3941</td></tr><tr><td>10</td><td>E</td><td>695112.3850</td><td>2837616.1751</td></tr><tr><td>E</td><td>F</td><td>695063.2475</td><td>2837406.3076</td></tr><tr><td>F</td><td>A</td><td>695242.6305</td><td>2837365.3472</td></tr><tr><td>A</td><td>14</td><td>695197.2179</td><td>2837166.4661</td></tr><tr><td>14</td><td>15</td><td>695679.8860</td><td>2837056.2533</td></tr><tr><td>15</td><td>15a</td><td>695847.9411</td><td>2837774.8154</td></tr><tr><td>15a</td><td>6a</td><td>695897.8667</td><td>2837987.7571</td></tr></tbody></table>\n<table><thead><tr><th colspan=\"4\">CUADRO DE CONSTRUCCIÓN DEL POLIGONO 2</th></tr><tr><th colspan=\"2\">LADO</th><th colspan=\"2\">COORDENADAS UTM 12 N</th></tr><tr><th>Estación</th><th>Punto visado</th><th>COORDENADA EN X</th><th>COORDENADA EN Y</th></tr></thead><tbody><tr><td>1</td><td>2</td><td>695702.1600</td><td>2836541.0900</td></tr><tr><td>2</td><td>3</td><td>695690.4042</td><td>2836547.6559</td></tr><tr><td>3</td><td>4</td><td>695700.8440</td><td>2836594.0909</td></tr><tr><td>4</td><td>5</td><td>695667.8156</td><td>2836628.5628</td></tr><tr><td>5</td><td>6</td><td>695724.8958</td><td>2836873.0865</td></tr><tr><td>6</td><td>7</td><td>696024.3108</td><td>2836845.9159</td></tr><tr><td>7</td><td>8</td><td>696022.6329</td><td>2837042.9286</td></tr><tr><td>8</td><td>9</td><td>695766.7817</td><td>2837052.5152</td></tr><tr><td>9</td><td>10</td><td>695809.9496</td><td>2837237.4403</td></tr><tr><td>10</td><td>11</td><td>695891.9600</td><td>2837385.7200</td></tr><tr><td>11</td><td>12</td><td>695906.5760</td><td>2837448.5451</td></tr><tr><td>12</td><td>13</td><td>695947.8466</td><td>2837449.4102</td></tr><tr><td>13</td><td>14</td><td>696228.0079</td><td>2838653.6505</td></tr><tr><td>14</td><td>15</td><td>696397.7055</td><td>2838690.5856</td></tr><tr><td>15</td><td>16</td><td>697042.7794</td><td>2838347.7066</td></tr><tr><td>16</td><td>17</td><td>697030.8730</td><td>2837912.6971</td></tr><tr><td>17</td><td>18</td><td>696998.6375</td><td>2837897.9214</td></tr><tr><td>18</td><td>19</td><td>697003.9617</td><td>2837844.9221</td></tr><tr><td>19</td><td>20</td><td>696968.6558</td><td>2837777.0582</td></tr><tr><td>20</td><td>21</td><td>697013.3688</td><td>2837728.9603</td></tr><tr><td>21</td><td>22</td><td>697029.4122</td><td>2837741.7547</td></tr><tr><td>22</td><td>23</td><td>697024.6098</td><td>2837373.1597</td></tr><tr><td>23</td><td>24</td><td>697062.5428</td><td>2837317.9725</td></tr><tr><td>24</td><td>25</td><td>697116.9647</td><td>2837286.9031</td></tr><tr><td>25</td><td>26</td><td>696848.1758</td><td>2836752.3463</td></tr><tr><td>26</td><td>27</td><td>696802.6233</td><td>2836773.0543</td></tr><tr><td>27</td><td>28</td><td>696720.5403</td><td>2836609.8108</td></tr><tr><td>28</td><td>1</td><td>696161.3604</td><td>2836311.6191</td></tr></tbody></table>\n<p>...</p>\n<p>...&quot;</p>","tipo_articulo":"ordinario","titulo_nombre":"Topolobampo","capitulo_nombre":"Acuerdo modificatorio","seccion_nombre":null},{"id":"17acff44-acc9-5e15-9f0b-2ff1d8a4873b","ley_id":"1f700fdd-9eca-53fe-8188-45988d86394d","orden":3,"identificador":"Transitorio único","contenido":"<p>TRANSITORIO</p>\n<p>ÚNICO. El presente Acuerdo entra en vigor el día de su publicación en el Diario Oficial de la Federación.</p>","tipo_articulo":"transitorio","titulo_nombre":"Topolobampo","capitulo_nombre":"Acuerdo modificatorio","seccion_nombre":null},{"id":"298e5efb-5638-5b69-8a66-bf749de25150","ley_id":"1f700fdd-9eca-53fe-8188-45988d86394d","orden":4,"identificador":"Firma","contenido":"<p>Ciudad de México, a los 20 días de abril de 2026.- El Secretario de Economía, Marcelo Luis Ebrard Casaubon.- Rúbrica.</p>","tipo_articulo":"complementario","titulo_nombre":"Topolobampo","capitulo_nombre":"Acuerdo modificatorio","seccion_nombre":null},{"id":"1ca90ba1-4d95-5439-9c19-6adfd5b4c978","ley_id":"1f700fdd-9eca-53fe-8188-45988d86394d","orden":5,"identificador":"Nota editorial · declaratoria original","tipo_articulo":"complementario","titulo_nombre":"Topolobampo","capitulo_nombre":"Documentos relacionados","seccion_nombre":null,"contenido":"<p><a href=\"#ley-0600bc5a-3691-5d6a-aa6d-1fffd931d6eb\">Texto original · ACUERDO por el que se emite la Declaratoria del Polo de Desarrollo Económico para el Bienestar Topolobampo, Sinaloa.</a></p>"}]}$polo$::jsonb;
  ley jsonb := paquete->'ley';
  ley_uuid uuid := (ley->>'id')::uuid;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(ley->>'url_original', 0));
  IF EXISTS (SELECT FROM public.leyes WHERE id <> ley_uuid AND (siglas = ley->>'siglas' OR url_original = ley->>'url_original')) THEN
    RAISE EXCEPTION 'Declaratoria registrada con otro ID: %', ley->>'siglas';
  END IF;
  INSERT INTO public.leyes (id, siglas, titulo, tipo, fecha_publicacion, url_original, temas_clave)
  SELECT id, siglas, titulo, tipo, fecha_publicacion, url_original, temas_clave FROM jsonb_populate_record(null::public.leyes, ley)
  ON CONFLICT (id) DO NOTHING;
  INSERT INTO public.articulos (id, ley_id, identificador, contenido, tipo_articulo, orden, titulo_nombre, capitulo_nombre, seccion_nombre)
  SELECT id, ley_id, identificador, contenido, tipo_articulo, orden, titulo_nombre, capitulo_nombre, seccion_nombre
  FROM jsonb_populate_recordset(null::public.articulos, paquete->'articulos') ON CONFLICT (id) DO NOTHING;
  IF NOT EXISTS (SELECT FROM public.leyes l WHERE l.id = ley_uuid AND to_jsonb(l) @> ley)
     OR EXISTS (SELECT FROM jsonb_array_elements(paquete->'articulos') a WHERE NOT EXISTS (
       SELECT FROM public.articulos t WHERE t.id = (a->>'id')::uuid AND to_jsonb(t) @> a)) THEN
    RAISE EXCEPTION 'El registro existente difiere del cotejo de %', ley->>'siglas';
  END IF;
  UPDATE public.articulos SET contenido='<p>Esta ficha reproduce la declaratoria original. Consulte la publicación posterior en el DOF: <a href="https://sidof.segob.gob.mx/notas/docFuente/5786253">Acuerdo modificatorio del 29/04/2026</a>.</p><p><a href="#ley-1f700fdd-9eca-53fe-8188-45988d86394d">Acuerdo modificatorio en el acervo</a></p>' WHERE id='a64be197-eb3f-5cd6-b740-16fd92e85c66' AND ley_id='0600bc5a-3691-5d6a-aa6d-1fffd931d6eb' AND contenido='<p>Esta ficha reproduce la declaratoria original. Consulte la publicación posterior en el DOF: <a href="https://sidof.segob.gob.mx/notas/docFuente/5786253">Acuerdo modificatorio del 29/04/2026</a>.</p>';
  IF NOT EXISTS (SELECT FROM public.articulos WHERE id='a64be197-eb3f-5cd6-b740-16fd92e85c66' AND ley_id='0600bc5a-3691-5d6a-aa6d-1fffd931d6eb' AND contenido='<p>Esta ficha reproduce la declaratoria original. Consulte la publicación posterior en el DOF: <a href="https://sidof.segob.gob.mx/notas/docFuente/5786253">Acuerdo modificatorio del 29/04/2026</a>.</p><p><a href="#ley-1f700fdd-9eca-53fe-8188-45988d86394d">Acuerdo modificatorio en el acervo</a></p>') THEN
    RAISE EXCEPTION 'La guía de la declaratoria original difiere del cotejo';
  END IF;
END
$carga$;
